import { type ElementType, forwardRef, type HTMLAttributes } from "react"
import { Slot } from "../lib/primitives/slot"
import { cx } from "../lib/utils/cx"
import { type BoxSpace, space, vars } from "./space"

export type BoxSurface = "none" | "surface" | "raised" | "sunken" | "muted" | "accent"
export type BoxRadius = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "full"
export type BoxShadow = "none" | "xs" | "sm" | "md" | "lg"

export interface BoxProps extends HTMLAttributes<HTMLElement> {
  /** The element to render. */
  as?: ElementType
  /** Merges the box onto its only child instead of rendering an element. */
  asChild?: boolean
  /** Padding on every side: a spacing step or a CSS length. */
  padding?: BoxSpace
  paddingX?: BoxSpace
  paddingY?: BoxSpace
  surface?: BoxSurface
  radius?: BoxRadius
  /** A hairline border; `strong` draws the 2px ink edge of a paper sheet. */
  border?: boolean | "strong"
  shadow?: BoxShadow
}

const SURFACE: Record<BoxSurface, string> = {
  none: "",
  surface: "bg-kg-surface",
  raised: "bg-kg-surface-raised",
  sunken: "bg-kg-surface-sunken",
  muted: "bg-kg-muted",
  accent: "bg-kg-paper-sage text-kg-fg",
}

const RADIUS: Record<BoxRadius, string> = {
  none: "rounded-none",
  sm: "rounded-kg-sm",
  md: "rounded-kg-md",
  lg: "rounded-kg-lg",
  xl: "rounded-kg-xl",
  "2xl": "rounded-kg-2xl",
  full: "rounded-full",
}

const SHADOW: Record<BoxShadow, string> = {
  none: "",
  xs: "shadow-kg-xs",
  sm: "shadow-kg-sm",
  md: "shadow-kg-md",
  lg: "shadow-kg-lg",
}

/** The base layout block: padding, surface, radius, border and shadow from tokens. */
export const Box = forwardRef<HTMLElement, BoxProps>(
  (
    {
      as: Tag = "div",
      asChild = false,
      padding,
      paddingX,
      paddingY,
      surface,
      radius,
      border,
      shadow,
      className,
      style,
      ...props
    },
    ref,
  ) => {
    const Component: ElementType = asChild ? Slot : Tag
    return (
      <Component
        ref={ref}
        className={cx(
          "kg-box box-border min-w-0 py-[var(--_py,var(--_p,0))] px-[var(--_px,var(--_p,0))]",
          surface && SURFACE[surface],
          radius && RADIUS[radius],
          border === "strong" ? "border-2 border-kg-ink" : border && "border border-kg-border",
          shadow && SHADOW[shadow],
          className,
        )}
        data-surface={surface && surface !== "none" ? surface : undefined}
        data-radius={radius}
        data-border={border === true ? "" : border || undefined}
        data-shadow={shadow && shadow !== "none" ? shadow : undefined}
        style={{
          ...vars({
            "--_p": space(padding),
            "--_px": space(paddingX),
            "--_py": space(paddingY),
          }),
          ...style,
        }}
        {...props}
      />
    )
  },
)

Box.displayName = "Box"

/**
 * A step on the spacing scale (multiples of `--kg-space`, so density scales it) or any CSS
 * length such as `"2rem"` or `"5vw"`.
 */
export type BoxSpace = number | string

/** Resolves a scale step or a length to a CSS value. */
export const space = (value: BoxSpace | undefined): string | undefined => {
  if (value === undefined) return undefined
  if (typeof value === "number") return value === 0 ? "0" : `calc(var(--kg-space) * ${value})`
  return value
}

/** Builds a style object of private custom properties, skipping the unset ones. */
export const vars = (
  entries: Record<string, string | number | undefined>,
): Record<string, string | number> => {
  const out: Record<string, string | number> = {}
  for (const [key, value] of Object.entries(entries)) if (value !== undefined) out[key] = value
  return out
}

export type BoxAlign = "start" | "center" | "end" | "stretch" | "baseline"
export type BoxJustify = "start" | "center" | "end" | "between" | "around" | "evenly"

const JUSTIFY: Record<BoxJustify, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  between: "space-between",
  around: "space-around",
  evenly: "space-evenly",
}

const ALIGN: Record<BoxAlign, string> = {
  start: "flex-start",
  center: "center",
  end: "flex-end",
  stretch: "stretch",
  baseline: "baseline",
}

export const justifyValue = (value: BoxJustify | undefined) =>
  value ? JUSTIFY[value] : undefined

export const alignValue = (value: BoxAlign | undefined) => (value ? ALIGN[value] : undefined)
